# ---------------- Prelims GS Paper I ----------------
E(1, "ca-to-static", "pre-1", ["prelims-gs"], "Every news story hides a static topic", "Current affairs: read the news, answer from the book", "globe",
  ["UPSC Civil Services Examination notice: Prelims GS Paper I syllabus", "Press Information Bureau (pib.gov.in)"],
  "A: Current affairs feels endless. How do you prepare for it? | B: By treating every news story as a doorway to a topic you already study.",
  [CH("The method", "Ask three things", [("What happened?", "One line, no more", "happened"), ("Which syllabus topic?", "Polity, economy, environment…", "syllabus"), ("What is static behind it?", "The Act, the body, the place", "static")],
      "A: For each story, ask what happened, in one line. | B: Then ask which syllabus topic it belongs to, and what static fact sits behind it."),
   QT("An example", "News: a new Ramsar site. Static: the Ramsar Convention, 1971.",
      "A: Say a wetland becomes a Ramsar site. | B: The question may ask about the convention itself, signed in Iran in 1971."),
   CH("Where to read", "Primary sources first", [("PIB", "What the government actually said", "PIB"), ("Official reports", "Budget, Economic Survey, India Year Book", "reports")],
      "A: Read the press release, not only the commentary. | B: And keep the Budget and the Economic Survey close.")],
  QZ("A wetland is in the news as a new Ramsar site. Which static fact is most worth checking?", ["The town's population", "The convention's year and place", "The reporter's name", "The day of the announcement"], 1,
     "Right. Prelims usually asks about the convention: Ramsar, Iran, 1971.", "A: Your turn. | B: Which static fact is most worth checking?"),
  note="Method piece; the only fact is the Ramsar Convention (1971, Ramsar, Iran).")

E(2, "inc-1885", "pre-2", ["prelims-gs", "mains-gs1"], "The Congress began as 72 delegates in Bombay", "1885: the Indian National Congress is born", "scroll",
  ["NCERT Class 8, Our Pasts III, ch. 9 'The Making of the National Movement'", "Bipan Chandra, India's Struggle for Independence"],
  "A: The party that led the freedom struggle started as a small meeting. | B: Seventy-two delegates, in Bombay, in December 1885.",
  [TL("How it began", [(1885, "First session, Bombay", "1885"), (1905, "Partition of Bengal", "1905"), (1920, "Non-Cooperation", "1920")],
      "A: The first session met in Bombay in 1885. | B: Twenty years later, the Partition of Bengal in 1905 turned it into a mass movement, and Non-Cooperation came in 1920."),
   QT("Who was there", "President: W. C. Bonnerjee. Founder figure: A. O. Hume, a retired civil servant.",
      "A: W. C. Bonnerjee was its first president. | B: And A. O. Hume, a retired British civil servant, helped bring it together."),
   CH("Early demands", "The Moderates asked for", [("More Indians in councils", "Expanded legislatures", "councils"), ("Civil service exams in India", "Not only in London", "exams")],
      "A: The early Moderates asked for more Indians in the legislative councils. | B: And for the civil service exams to be held in India too.")],
  QZ("Who presided over the first session of the Indian National Congress?", ["Dadabhai Naoroji", "W. C. Bonnerjee", "A. O. Hume", "Surendranath Banerjea"], 1,
     "Right. W. C. Bonnerjee presided over the 1885 Bombay session.", "A: Your turn. | B: Who presided over the first session?"))

E(3, "tropic-of-cancer", "pre-3", ["prelims-gs", "mains-gs1"], "The Tropic of Cancer crosses eight Indian states", "Eight states on one line of latitude", "compass",
  ["NCERT Class 9, Contemporary India I, ch. 1 'India: Size and Location'", "Survey of India"],
  "A: One line of latitude runs right across India. | B: The Tropic of Cancer, at about twenty-three and a half degrees north.",
  [MP([[80, 22], 2.4], [("Gujarat", [72, 23.5], 4.2), ("Mizoram", [90, 23.5], 4.2)], [([69.5, 23.44], "Gujarat · west end", "Gujarat"), ([92.8, 23.44], "Mizoram · east end", "Mizoram")],
      "A: It enters India in Gujarat. | B: And leaves through Mizoram, in the east."),
   CH("The eight states", "West to east", [("Gujarat · Rajasthan · Madhya Pradesh · Chhattisgarh", "The western half", "Rajasthan"), ("Jharkhand · West Bengal · Tripura · Mizoram", "The eastern half", "Jharkhand")],
      "A: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh. | B: Then Jharkhand, West Bengal, Tripura and Mizoram."),
   QT("A handy trick", "It splits India into two nearly equal halves: north and south.",
      "A: It roughly divides the country in half. | B: Which is why it shows up in so many map questions.")],
  QZ("Which of these states does the Tropic of Cancer NOT pass through?", ["Tripura", "Odisha", "Jharkhand", "Chhattisgarh"], 1,
     "Right. Odisha lies south of the Tropic of Cancer.", "A: Your turn. | B: Which state does it not pass through?"))

E(4, "fundamental-rights", "pre-4", ["prelims-gs", "mains-gs2"], "Fundamental Rights: Articles 12 to 35", "Six Fundamental Rights, and one that left", "constitution",
  ["Constitution of India, Part III", "Constitution (Forty-fourth Amendment) Act, 1978"],
  "A: The Constitution began with seven Fundamental Rights. | B: Today there are six. Where did the seventh go?",
  [CH("The six today", "Part III, Articles 12 to 35", [("Equality · Freedom", "Articles 14 to 22", "Equality"), ("Against exploitation · Religion", "Articles 23 to 28", "exploitation"), ("Culture and education · Remedies", "Articles 29 to 32", "Culture")],
      "A: Equality and freedom. Against exploitation, and freedom of religion. | B: Cultural and educational rights, and the right to constitutional remedies."),
   TL("The missing right", [(1950, "Property is a Fundamental Right", "1950"), (1978, "44th Amendment removes it", "1978")],
      "A: The right to property was a Fundamental Right in 1950. | B: The forty-fourth amendment of 1978 removed it. It is now a legal right, under Article 300A."),
   QT("Article 32", "\"The very soul of the Constitution and the very heart of it.\"",
      "A: Article 32 lets you go straight to the Supreme Court if a right is violated. | B: Ambedkar called it the very soul of the Constitution, and the very heart of it.", by="B. R. Ambedkar, Constituent Assembly")],
  QZ("Under which Article is the right to property now protected?", ["Article 19", "Article 31", "Article 300A", "Article 32"], 2,
     "Right. Since the 44th Amendment (1978) it is a constitutional legal right under Article 300A.", "A: Your turn. | B: Where is the right to property now?"))

E(5, "hdi", "pre-5", ["prelims-gs", "mains-gs3"], "The Human Development Index measures more than income", "HDI: health, education and income in one number", "people",
  ["UNDP Human Development Report (hdr.undp.org), technical notes"],
  "A: A country can grow richer without its people living better. | B: That gap is why the Human Development Index exists.",
  [TL("Where it comes from", [(1990, "First Human Development Report", "1990")],
      "A: The UNDP published the first Human Development Report in 1990. | B: It drew on the work of Mahbub ul Haq and Amartya Sen."),
   CH("Three dimensions", "What HDI measures", [("A long and healthy life", "Life expectancy at birth", "long"), ("Knowledge", "Years of schooling", "Knowledge"), ("A decent standard of living", "Gross national income per person", "standard")],
      "A: A long and healthy life, measured by life expectancy. | B: Knowledge, through years of schooling. And a decent standard of living, through income per person."),
   QT("For Mains", "Growth is a means. Human development is the end.",
      "A: In G-S-three answers, use it to separate growth from development. | B: Growth is a means. Human development is the end.")],
  QZ("Which body publishes the Human Development Index?", ["World Bank", "IMF", "UNDP", "NITI Aayog"], 2,
     "Right. The UNDP publishes it in the Human Development Report.", "A: Your turn. | B: Who publishes the H-D-I?"))

E(6, "ramsar", "pre-6", ["prelims-gs", "mains-gs3"], "Ramsar sites are wetlands of international importance", "Ramsar: a treaty for wetlands", "forest",
  ["Ramsar Convention Secretariat (ramsar.org)", "Ministry of Environment, Forest and Climate Change"],
  "A: The oldest modern treaty on an ecosystem is about wetlands. | B: It's named after a small town in Iran: Ramsar.",
  [TL("Key dates", [(1971, "Signed at Ramsar, Iran", "1971"), (1982, "India joins", "1982")],
      "A: It was signed in 1971. | B: India joined in 1982."),
   CH("India's first two", "Designated in 1981", [("Chilika Lake", "Odisha", "Chilika"), ("Keoladeo National Park", "Rajasthan", "Keoladeo")],
      "A: India's first Ramsar sites were Chilika Lake in Odisha | B: and Keoladeo National Park in Rajasthan."),
   QT("The Montreux Record", "A list of Ramsar sites where the ecology is changing for the worse.",
      "A: Sites under threat can go on the Montreux Record. | B: Keoladeo is on it. Chilika was taken off in 2002.")],
  QZ("The Ramsar Convention is about:", ["Ozone-depleting substances", "Wetlands", "Migratory species", "Desertification"], 1,
     "Right. It's the Convention on Wetlands, 1971.", "A: Your turn. | B: What is the Ramsar Convention about?"),
  note="Check the Montreux Record dates (Chilika removed 2002) and India's accession year against ramsar.org.")

E(7, "vitamins", "pre-7", ["prelims-gs"], "Four vitamins dissolve in fat, the rest in water", "Vitamins: what's missing shows up", "science",
  ["NCERT Class 6 Science, 'Components of Food'", "NCERT Class 10 and 11 Biology"],
  "A: General science questions love vitamins. | B: Two lists cover most of them.",
  [CH("Fat-soluble", "Stored in the body", [("A · D · E · K", "Taken in with fats, stored in the liver and fat", "A")],
      "A: Vitamins A, D, E and K dissolve in fat. | B: The body stores them, so too much can build up."),
   CH("Deficiency diseases", "Learn the pairs", [("A → night blindness", "D → rickets", "night"), ("C → scurvy", "B1 → beriberi", "scurvy")],
      "A: Too little vitamin A, and you get night blindness. Too little D, rickets. | B: Too little C causes scurvy. And too little B one, beriberi."),
   QT("Sunlight vitamin", "Skin makes vitamin D when sunlight falls on it.",
      "A: Vitamin D is the one your skin can make. | B: In sunlight.")],
  QZ("Which of these is a water-soluble vitamin?", ["Vitamin A", "Vitamin C", "Vitamin D", "Vitamin K"], 1,
     "Right. Vitamin C is water-soluble; A, D, E and K are fat-soluble.", "A: Your turn. | B: Which one is water-soluble?"))

# ---------------- CSAT ----------------
E(8, "csat-comprehension", "csat-1", ["prelims-csat"], "In CSAT, the passage is the only truth", "Comprehension: answer from the passage", "book",
  ["UPSC CSE notice: Prelims Paper II syllabus"],
  "A: The commonest CSAT mistake? | B: Answering from what you know, instead of what the passage says.",
  [CH("Three question types", "Know what's asked", [("Main idea", "What is the whole passage about?", "Main"), ("Inference", "What must be true, given the passage?", "Inference"), ("Assumption", "What does the author take for granted?", "Assumption")],
      "A: Main idea asks what the whole passage is about. | B: Inference asks what must follow. Assumption asks what the author takes for granted."),
   QT("A trap to spot", "An option can be true in real life and still be wrong.",
      "A: Watch for options that are true in the real world | B: but not supported by the passage. Those are wrong."),
   CH("Extreme words", "Treat with suspicion", [("always · never · only · all", "Rarely the right inference", "always")],
      "A: Options with always, never or only | B: are usually too strong to be the answer.")],
  QZ("In an inference question, the right option must be:", ["True in real life", "Supported by the passage", "The longest option", "Stated in the first line"], 1,
     "Right. An inference must follow from the passage itself.", "A: Your turn. | B: What must the right option be?"),
  note="Method piece; no factual claims beyond the syllabus wording.")

E(9, "syllogism", "csat-2", ["prelims-csat"], "Some is not the same as all", "Syllogisms: draw the circles", "puzzle",
  ["UPSC CSE notice: Prelims Paper II syllabus", "Standard logic texts on categorical syllogisms"],
  "A: All doctors are graduates. Some graduates are singers. | B: So, are some doctors singers? Not necessarily.",
  [QT("Why not", "The singers may be graduates who are not doctors.",
      "A: Draw a circle for graduates, with doctors inside it. | B: The singers can sit in the part of the graduate circle that has no doctors."),
   CH("Safe rules", "What does follow", [("All A are B + All B are C", "→ All A are C", "All"), ("Some A are B", "→ Some B are A", "Some")],
      "A: If all A are B, and all B are C, then all A are C. | B: And if some A are B, then some B are A. That one always reverses."),
   QT("The habit", "If a counter-example exists, the conclusion does not follow.",
      "A: Try to build one picture where the conclusion fails. | B: If you can, the conclusion does not follow.")],
  QZ("All pens are blue. Some blue things are cheap. Which follows?", ["Some pens are cheap", "No pen is cheap", "Neither conclusion follows", "All cheap things are pens"], 2,
     "Right. The cheap blue things may not be pens, and nothing rules out a cheap pen either.", "A: Your turn. | B: Which conclusion follows?"))

