E(11, "clock-angle", "csat-4", ["prelims-csat"], "One formula solves clock angles", "Clock angles: 30H minus 5.5M", "compass",
  ["Standard quantitative aptitude texts"],
  "A: What's the angle between the hands at 3:15? | B: Not zero. Here's why.",
  [CH("The speeds", "Per minute", [("Minute hand: 6°", "360° in 60 minutes", "Minute"), ("Hour hand: 0.5°", "30° in 60 minutes", "Hour")],
      "A: The minute hand moves 6 degrees a minute. | B: The hour hand moves half a degree a minute, so it creeps forward too."),
   QT("The formula", "Angle = | 30 × H − 5.5 × M |",
      "A: Angle equals 30 times the hour, minus 5.5 times the minutes. | B: Take the size, ignore the sign."),
   ST("At 3:15", [(7.5, "°", "not zero", "7")],
      "A: 30 times 3 is 90. 5.5 times 15 is 82.5. | B: So the angle is 7.5 degrees.")],
  QZ("What is the angle between the hands at 9:00?", ["45°", "90°", "180°", "270°"], 1,
     "Right. |30×9 − 0| = 270°, and the smaller angle is 360 − 270 = 90°.", "A: Your turn. | B: What's the angle at nine o'clock?"),
  note="If the formula gives more than 180°, take 360 minus it.")

E(12, "percent-change", "csat-5", ["prelims-csat"], "Up 20, down 20 is not back to start", "Percentages: the base changes", "chart",
  ["Standard quantitative aptitude texts"],
  "A: A price rises 20 percent, then falls 20 percent. | B: Is it back where it started? No.",
  [ST("Step by step", [(120, "", "after +20% on 100", "120"), (96, "", "after −20% on 120", "96")],
      "A: Start at 100. Up 20 percent makes 120. | B: Down 20 percent of 120 is 24. That leaves 96."),
   QT("The shortcut", "Net change = a + b + (a × b ÷ 100)",
      "A: Add the two changes, plus their product over 100. | B: 20 minus 20, minus 4. A net fall of 4 percent."),
   CH("In data tables", "Read the base", [("Percent change", "Grows or falls from the old value", "Percent"), ("Percentage points", "A plain difference of two rates", "points")],
      "A: Percent change and percentage points are different. | B: A rate going from 4 to 5 percent is one point, but a 25 percent rise.")],
  QZ("A salary is raised 10% and then cut 10%. The net change is:", ["No change", "1% fall", "1% rise", "2% fall"], 1,
     "Right. 10 − 10 − (10×10/100) = −1%.", "A: Your turn. | B: What's the net change?"))

